---@field ImgIcon                       	UnityEngine.RectTransform               	@ 5    
---@field TxtNum                        	UnityEngine.RectTransform               	@ 6    
local ResidentBondPanelDayCell = Class("ResidentBondPanelDayCell")

function ResidentBondPanelDayCell:__init()
    self.rewardVo = nil
    self.isGet = false
    self.isCanGet = false
    self.index = nil
    self.data = nil
    self.callBack = nil
end

function ResidentBondPanelDayCell:__delete()
    self.index = nil
    self.data = nil
    self.rewardVo = nil
    self.isGet = nil
    self.isCanGet = nil
    self.callBack = nil
    self.controller = nil
end

function ResidentBondPanelDayCell:Awake()
    SetButtonAction(self.BtnReward,Bind(self,self.OnBtnRewardClick))
end

function ResidentBondPanelDayCell:InitCallBack(cb)
    self.callBack = cb
end

function ResidentBondPanelDayCell:RefreshShow(index, serverData)
    self.index = index
    self.data = serverData

    local isGet = self:IsGetReward(self.index)
    self.isGet = isGet
    local state = isGet and 1 or 2
    CfUtils.SetUISwitchText(self.TxtDay,state)
    CfUtils.SetActive(self.ImgGet.gameObject,isGet)
    CfUtils.SetUISwitchText(self.TxtNum,isGet and 2 or 1)
    CfUtils.SetUISwitchImage(self.ImgBg,isGet and 2 or 1)
    local rewardVo = CfUtils.GetCfVo(AutoIds.IdSetting6445,"DailyInvestRewardsVo",self.index)
    self.rewardVo = rewardVo
    if isGet then
        CfUtils.SetActive(self.CanReceive.gameObject,false)
        CfUtils.SetActive(self.UIFX_Target.gameObject,true)
    else
        if isNotNull(rewardVo) then
            local isCanGet = checkNumber(self.data.investCheckinTimes) >= rewardVo.payTime
            self.isCanGet = isCanGet
            CfUtils.SetActive(self.CanReceive.gameObject,isCanGet)
            CfUtils.SetActive(self.UIFX_Target.gameObject,isCanGet)
        end
    end

    if isNotNull(rewardVo) then
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(rewardVo.rewardId)
        if isNotNull(goodsVo) then
            CfUtils.FillImage(self.ImgIcon,goodsVo.photoPath)
        end
        CfUtils.FillText(self.TxtNum,rewardVo.RewardsNum)
    end
end

function ResidentBondPanelDayCell:IsGetReward(id)
    for i, v in ipairs(self.data.drawInvestRewardIds) do
        if tonumber(v) == tonumber(id) then
            return true
        end
    end
    return false
end

function ResidentBondPanelDayCell:OnBtnRewardClick()
    if self.isGet then
        GameUtils.Toast(localize("奖励已领取"))
        return
    end

    if not self.isCanGet then
        GameUtils.Toast(localize("投资_day_天后可领取奖励",{_day_ = self.rewardVo.payTime}))
        return
    end

    if self.callBack then
        self.callBack(self.index)
    end
end

function ResidentBondPanelDayCell:OnDestroy()
    self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
    self:Delete()
end

return ResidentBondPanelDayCell